<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Response.php';require_once __DIR__.'/../lib/DocsRepository.php';Auth::requirePermission('docs.manage');$pageTitle='مستندات و آموزش';$adminExtraStylesheets=['/assets/css/workforce.css'];$q=trim((string)($_GET['q']??''));$category=(int)($_GET['category_id']??0);$status=(string)($_GET['status']??'');$scope=(string)($_GET['scope']??'');$where=['1=1'];$params=[];if($q!==''){$where[]='(a.title LIKE ? OR a.summary LIKE ? OR a.content LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);}if($category){$where[]='a.category_id=?';$params[]=$category;}if($status!==''){$where[]='a.active=?';$params[]=$status==='active'?1:0;}if(in_array($scope,['all','units','roles','users'],true)){$where[]='a.visibility_scope=?';$params[]=$scope;}$items=Database::fetchAll('SELECT a.*,c.title category_title,u.name creator_name,(SELECT COUNT(*) FROM docs_read_logs l WHERE l.doc_id=a.id) read_count,(SELECT COUNT(*) FROM docs_read_logs l WHERE l.doc_id=a.id AND l.confirmed_at IS NOT NULL) confirmed_count FROM docs_articles a LEFT JOIN docs_categories c ON c.id=a.category_id LEFT JOIN users u ON u.id=a.created_by WHERE '.implode(' AND ',$where).' ORDER BY a.id DESC',$params);$categories=DocsRepository::categories();require __DIR__.'/../views/partials/admin-header.php';?>
<div class="workforce-head"><div><h1>مستندات و آموزش</h1><p>راهنماها، فایل‌های داخلی و تایید مطالعه</p></div><a class="btn btn-primary" href="/admin/docs-edit.php">مستند جدید</a></div><nav class="workforce-tabs"><a class="is-active" href="/admin/docs.php">مستندات</a><a href="/admin/docs-categories.php">دسته‌بندی‌ها</a><a href="/admin/docs-view-logs.php">گزارش مطالعه</a></nav><section class="card"><form method="get" class="compact-grid"><label class="form-field"><span>جستجو</span><input name="q" value="<?=e($q)?>"></label><label class="form-field"><span>دسته</span><select name="category_id"><option value="">همه</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>" <?=$category===$c['id']?'selected':''?>><?=e($c['title'])?></option><?php endforeach?></select></label><label class="form-field"><span>سطح دسترسی</span><select name="scope"><option value="">همه</option><?php foreach(['all'=>'همه کاربران','units'=>'واحدها','roles'=>'نقش‌ها','users'=>'کاربران'] as $k=>$v):?><option value="<?=$k?>" <?=$scope===$k?'selected':''?>><?=$v?></option><?php endforeach?></select></label><label class="form-field"><span>وضعیت</span><select name="status"><option value="">همه</option><option value="active" <?=$status==='active'?'selected':''?>>فعال</option><option value="inactive" <?=$status==='inactive'?'selected':''?>>غیرفعال</option></select></label><div class="form-actions"><button class="btn btn-primary">فیلتر</button></div></form></section><section class="card"><div class="table-wrap"><table><thead><tr><th>مستند</th><th>دسته</th><th>دسترسی</th><th>مطالعه / تایید</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><strong><?=e($i['title'])?></strong><small class="muted"><?=e($i['summary'])?></small></td><td><?=e($i['category_title']?:'—')?></td><td><?=e(['all'=>'همه کاربران','units'=>'واحدهای منتخب','roles'=>'نقش‌های منتخب','users'=>'کاربران منتخب'][$i['visibility_scope']]??'')?></td><td><?=$i['read_count']?> / <?=$i['confirmed_count']?></td><td><?=(int)$i['active']?'فعال':'غیرفعال'?></td><td><div class="form-actions"><a class="btn btn-small" href="/employee/doc-view.php?id=<?=$i['id']?>">مشاهده</a><a class="btn btn-small" href="/admin/docs-edit.php?id=<?=$i['id']?>">ویرایش</a><a class="btn btn-small" href="/admin/docs-view-logs.php?doc_id=<?=$i['id']?>">گزارش</a></div></td></tr><?php endforeach?><?php if(!$items):?><tr><td colspan="6">مستندی پیدا نشد.</td></tr><?php endif?></tbody></table></div></section><?php require __DIR__.'/../views/partials/admin-footer.php';?>
